namespace generic.util;




public class FileChannelLock {

	private File lockFile;
	private FileOutputStream @out;
	private FileChannel fc;
	private FileLock @lock;

	/**
	 * A flag to signal that we are locked.  This is needed because we do not want to 'cleanup'
	 * lock files when we can't lock, as they may already be in use by another application 
	 * instance.
	 */
	private bool isLocked;

	public FileChannelLock(File lockFile) {
		this.lockFile = new File(lockFile.getAbsolutePath() + "~");
	}

	bool @lock() {
		try {
			@out = new FileOutputStream(lockFile, true);
			fc = @out.getChannel();
			@lock = fc.tryLock();
			isLocked = (@lock != null);

			if (!isLocked) {
				release();
			}

			return isLocked;
		}
		catch (Exception e) when (e is IOException or OverlappingFileLockException) {
			release();
		}
		return false;
	}

	void release() {
		if (@lock != null) {
			try {
				@lock.release();
			}
			catch (IOException e) {
				// we tried
			}
		}
		if (fc != null) {
			try {
				fc.close();
			}
			catch (IOException e) {
				// we tried
			}
		}
		if (@out != null) {
			try {
				@out.close();
			}
			catch (IOException e) {
				// we tried
			}
		}

		if (isLocked) {
			// only try to delete the lock file if we were able to lock
			lockFile.delete();
		}
	}
}
